}

header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255, 255, 255, 0.8);
  backdrop-filter: blur(20px);
  border-bottom: 1px solid rgba(0, 0, 0, 0.1);
}

.nav-container {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem 2rem;
}

.logo {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.5px;
}

nav ul {
  display: flex;
  list-style: none;
  gap: 2rem;
}

nav a {
  text-decoration: none;
  color: var(--text-main);
  font-size: 0.9rem;
  font-weight: 500;
  transition: opacity 0.2s;
}

nav a:hover {
  opacity: 0.6;
}

.hero {
  height: 80vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  background-color: var(--accent);
  padding: 2rem;
  margin-bottom: 4rem;
}

.hero-content h1 {
  font-size: 4rem;
  font-weight: 700;
  margin-bottom: 1rem;
  letter-spacing: -1px;
}

.hero-content p {
  font-size: 1.5rem;
  color: var(--text-muted);
  max-width: 600px;
  margin: 0 auto 2rem;
}

.btn {
  display: inline-block;
  padding: 12px 24px;
  border-radius: 980px;
  background: var(--primary);
  color: white;
  text-decoration: none;
  font-weight: 600;
  transition: transform 0.2s;
}

.btn:hover {
  transform: scale(1.05);
}

section {
  max-width: 1200px;
  margin: 4rem auto;
  padding: 0 2rem;
}

section h2 {
  font-size: 2.5rem;
  margin-bottom: 2rem;
  font-weight: 700;
}

.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 2rem;
}

.product-card {
  background: var(--accent);
  border-radius: 20px;
  padding: 2rem;
  transition: transform 0.3s ease;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  min-height: 400px;
}

.product-card:hover {
  transform: translateY(-5px);
}

.product-card h3 {
  font-size: 1.25rem;
  margin-bottom: 0.5rem;
}

.product-card .price {
  font-weight: 600;
  color: var(--text-muted);
}

.deals-section {
  background-color: #fbfbfd;
  padding: 4rem 0;
}

.deals-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
}

.deal-card {
  background: white;
  padding: 3rem;
  border-radius: 30px;
  border: 1px solid #f2f2f2;
}

.deal-card h3 {
  font-size: 2rem;
  margin-bottom: 1rem;
}

.editorial {
  display: flex;
  gap: 4rem;
  align-items: center;
}

.editorial-content {
  flex: 1;
}

.editorial-image {
  flex: 1;
  background: var(--accent);
  height: 500px;
  border-radius: 30px;
}

footer {
  background: #f5f5f7;
  padding: 4rem 2rem;
  margin-top: 6rem;
}

.footer-container {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
}

.footer-col h4 {
  margin-bottom: 1.5rem;
  font-size: 0.8rem;
  color: var(--text-muted);
  text-transform: uppercase;
}

.footer-col ul {
  list-style: none;
}

.footer-col li {
  margin-bottom: 0.8rem;
}

.footer-col a {
  text-decoration: none;
  color: var(--text-main);
  font-size: 0.8rem;
}

@media (max-width: 768px) {
  .hero-content h1 { font-size: 2.5rem; }
  .deals-grid { grid-template-columns: 1fr; }
  .editorial { flex-direction: column; }
  .footer-container { grid-template-columns: 1fr 1fr; }
}
