  font-size: 2.5rem;
  margin-bottom: 2rem;
  font-weight: 700;
}

.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 2rem;
}

.product-card {
  background: var(--accent);
  border-radius: 20px;
